{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ampicillin, a polar beta-lactam with ionizable groups, has absolute oral bioavailability of 48.1 ± 19.3% in nonpregnant women, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Meperidine, a basic tertiary amine ester with significant first-pass metabolism, has oral bioavailability of about 50%, supporting high F for basic ester-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Diphenhydramine, a basic ether with moderate first-pass metabolism, has absolute oral bioavailability of 69% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Felbamate, a polar dicarbamate, has oral bioavailability greater than 90%, showing that polar carbamates can be highly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Perindopril, an ester prodrug, has absolute oral bioavailability of about 75%, supporting high F for ester-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Rivastigmine, a carbamate with presystemic metabolism, has absolute oral bioavailability of 71.7% at a 6 mg dose, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Phenylethylmalonamide, a polar diamide, has almost complete oral bioavailability of 91 ± 4.4%, supporting high F for polar amide-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide, an epoxide-containing drug, has absolute oral bioavailability of 60%, supporting high F for epoxide-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "DEHP, a lipophilic diester, has oral bioavailability of about 25%, still above the 20% threshold despite extensive metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues with high transferability report absolute oral bioavailability values above the 20% threshold, mostly 36-95%, across ester, carbamate, amide, and epoxide-containing drugs. The query is therefore predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is available in the retrieved evidence.",
    "The analogues are structurally diverse, and transfer scores are high but not based on close chemical similarity to the tropane ester scaffold.",
    "First-pass metabolism for the specific tropane ester/epoxide scaffold is not directly measured in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

